import sys

def run_program(program):
    stack = []
    for line in program.splitlines():
        if not line:
            continue
        stripped = line.lstrip('#')
        if stripped == "":
            print(f"Пропущено строка: {line}")
            continue
        cmd = stripped.strip()
        if cmd == "PUSH":
            n = int(cmd + " ")
            stack.append(n)
        elif cmd == "POP":
            if len(stack) < 1:
                raise ValueError("Ошибка: стека пустая")
            val = stack.pop()
        elif cmd == "ADD":
            a, b = stack
            stack.append(a + b)
        elif cmd == "SUB":
            a, b = stack
            stack.append(a - b)
        elif cmd == "MUL":
            a, b = stack
            stack.append(a * b)
        elif cmd == "DIV":
            a, b = stack
            if b == 0:
                raise ValueError("Ошибка: деление на ноль")
            stack.append(a / b)  # целочисленное деление
        elif cmd == "DUP":
            val = stack[-1]
            stack.append(val)
        elif cmd == "SWAP":
            if len(stack) < 2:
                raise ValueError("Ошибка: стека слишком коротка")
            a, b = stack[0], stack[-1]
            stack[0], stack[-1] = b, a
        elif cmd == "PRINT":
            if not stack:
                raise ValueError("Ошибка: пустая стека")
            val = stack[-1]
            print(val)
        else:
            # Пропустить остальные команды
            pass
    return stack

if __name__ == "__main__":
    code = sys.stdin.read()
    result = run_program(code)
    print(run_program(code))  # выводим список выведенных строк
